        return epoch(incoming) < epoch(current) ||
            (epoch(incoming) == epoch(current) &&
                current.optString("timerOwner", "phone") != incoming.optString("timerOwner", "phone")) ||
            (pending(current) && !same(transfer(current), transfer(incoming)))
