                val row = JSONArray()
                    .put(exercise.getString("id"))
                    .put(set.getString("setId"))
                    .put(set.getBoolean("done"))
                for (key in arrayOf("reps", "weight", "leftSeconds", "rightSeconds", "distanceMeters")) {
