        for (i in 0 until left.length()) {
            val a = left.getJSONArray(i)
            val b = right.getJSONArray(i)
            if (a.length() != 8 || b.length() != 8) return false
            for (j in 0..2) {
                if (a.get(j) != b.get(j)) return false
