        val existing = current().cloudDeviceId
        if (existing.matches(Regex("[a-f0-9-]{36}"))) return existing
        val generated = UUID.randomUUID().toString().lowercase()
        context.trainPilotDataStore.edit { it[KEY_CLOUD_DEVICE_ID] = generated }
        return generated
    }

