        synchronized(LOCK) {
            val days = JSONArray()
            readableDatabase.rawQuery("SELECT day FROM dirty_days ORDER BY day LIMIT 500", null).use { c ->
                while (c.moveToNext()) days.put(c.getString(0))
            }
