    private fun pauseRun() {
        if (!running) {
            cancelVibration()
            return
        }
        update()
        cancelVibration()
        if (!running) return
        elapsed = now()
        running = false
        began = 0L
        handler.removeCallbacks(tick)
        release()
        DistanceTrackingService.pauseOwned(this, steps[gpsStep].gpsKey ?: "", true)
        save()
        notifyStatus()
        publishWatchClock()
    }

    private fun stopRun() {
        if (timeline == null) {
            stopForeground(STOP_FOREGROUND_REMOVE)
            stopSelf()
            return
        }
        pauseRun()
        stopped = true
        DistanceTrackingService.stopOwned(this, steps[gpsStep].gpsKey ?: "")
        save()
        publishWatchClock()
        stopForeground(STOP_FOREGROUND_REMOVE)
        stopSelf()
    }

    override fun onTaskRemoved(root: Intent?) {
        armedWorkoutId = ""
        if (timeline != null) {
            stopRun()
        } else {
            stopForeground(STOP_FOREGROUND_REMOVE)
            stopSelf()
        }
    }

    override fun onDestroy() {
        if (running) {
            cancelVibration()
            elapsed = now()
            running = false
            interrupted = true
            DistanceTrackingService.stopOwned(this, steps[gpsStep].gpsKey ?: "")
            save()
        }
        handler.removeCallbacks(tick)
        handler.removeCallbacks(expire)
        release()
        tones?.release()
        if (instance === this) instance = null
        super.onDestroy()
    }
}
