                    types.add(x.javaClass.simpleName)
                    addRecordDays(days, x)
                }
                val deletedRecords = JSONArray()
                for (d in r.deletedLogs) {
                    deletedRecords.put(
                        JSONObject()
                            .put("recordId", d.deletedRecordId)
                            .put("deletedMs", d.deletedTime.toEpochMilli())
                    )
