        val id = outgoing.getString("id"); val kind = outgoing.getString("kind")
        val attempt = outgoing.getString("sender") + ":" + id + ":" + kind
        synchronized(attempts) {
            val now = SystemClock.elapsedRealtime()
            if (attempts[attempt]?.let { now - it < 5_000L } == true) return
            if (attempts.size > 64) attempts.clear(); attempts[attempt] = now
        }
        val item = PutDataMapRequest.create(WorkoutOwnership193.PATH + outgoing.getString("sender") + "/" + id)
        item.dataMap.putString("ownership", outgoing.toString()); item.dataMap.putLong("retryAt", System.currentTimeMillis())
